// scripts/gen-provider-index.mjs — emit src/background/providers/index.js.
//
// The browser bundle cannot use fs.readdirSync + dynamic import to discover
// provider modules (see the _registry browser port), so the registry is a
// static module: one static import per provider, keyed by its id. This script
// regenerates it from the vendored tree.
//
// Run at build time (build.mjs) and as a `pretest` script so `npm test` never
// depends on a prior build. Idempotent: deterministically ordered output
// (alphabetical by file), so the generated file only changes when the tree
// changes.
//
// Every provider is scanned for the id its default export reports; a file
// whose default export carries no `id` is a hard error — a silently missing
// registry entry would break resolveProvider() routing at runtime.

import { readdirSync, writeFileSync } from 'node:fs';
import { join, resolve, dirname } from 'node:path';
import { fileURLToPath, pathToFileURL } from 'node:url';

const EXT = resolve(dirname(fileURLToPath(import.meta.url)), '..');
const PROVIDERS = join(EXT, 'src', 'background', 'providers');
const OUT = join(PROVIDERS, 'index.js');

const ids = [];
for (const name of readdirSync(PROVIDERS).sort()) {
  if (name.endsWith('.mjs') && !name.startsWith('_') && name !== 'helpers.mjs') {
    const mod = await import(pathToFileURL(join(PROVIDERS, name)).href);
    const id = mod.default && mod.default.id;
    if (typeof id !== 'string' || !id) {
      throw new Error(
        `gen-provider-index: ${name} has no string default-export id (got ${JSON.stringify(id)})`
      );
    }
    ids.push([name, id]);
  }
}

const lines = [];
lines.push('// DO NOT EDIT — generated by scripts/gen-provider-index.mjs.');
lines.push('// Static registry for the browser extension: the bundle cannot discover');
lines.push('// provider modules with fs.readdirSync + dynamic import (see _registry.mjs),');
lines.push('// so every provider is imported up front and keyed by id.');
lines.push('//');
lines.push(`// ${ids.length} providers. Regenerate with: npm run gen:provider-index`);
lines.push('');
for (let i = 0; i < ids.length; i++) {
  lines.push(`import * as _p${i} from ${JSON.stringify(`./${ids[i][0]}`)};`);
}
lines.push('');
lines.push('/** id → provider module default export. */');
lines.push('export const providerMap = {');
for (let i = 0; i < ids.length; i++) {
  lines.push(`  ${JSON.stringify(ids[i][1])}: _p${i}.default,`);
}
lines.push('};');
lines.push('');

writeFileSync(OUT, lines.join('\n'));
console.log(`gen-provider-index: wrote ${OUT} with ${ids.length} providers`);
